 const palettes=[['#4f7048','#c7b77c','#794c2d','#765038'],['#8e3e4e','#edc57e','#8e482e','#693a2f'],['#344e70','#c9b580','#d2d6d0','#554b46'],['#63814e','#c8ac6d','#493c32','#5c4230'],['#e7d8b1','#bda45e','#e6be66','#857054'],['#357b80','#b6b590','#39667e','#704c33']];
